export function useAsync(fn) {
  const [estado, setEstado] = useState({ fase: "inicial", dato: null, error: null });

  const ejecutar = useCallback(
    async (...args) => {
      setEstado(/* cargando */);
      try {
        const dato = await fn(...args);
        setEstado(/* listo */);
        return dato;
      } catch (error) {
        setEstado(/* error */);
      }
    },
    [fn],
  );

  return { ...estado, ejecutar };
}
